// Web Audio API Sound Synthesizer for Space Tourism
class SpaceAudioSynthesizer {
  constructor() {
    this.audioCtx = null;
    this.ambientGain = null;
    this.isAmbientPlaying = false;
    this.oscillators = [];
  }

  initContext() {
    if (!this.audioCtx) {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (AudioContext) {
        this.audioCtx = new AudioContext();
      }
    }
    if (this.audioCtx && this.audioCtx.state === 'suspended') {
      this.audioCtx.resume();
    }
  }

  toggleAmbientSound() {
    this.initContext();
    if (!this.audioCtx) return false;

    if (this.isAmbientPlaying) {
      this.stopAmbientSound();
      return false;
    } else {
      this.startAmbientSound();
      return true;
    }
  }

  startAmbientSound() {
    if (this.isAmbientPlaying || !this.audioCtx) return;

    this.ambientGain = this.audioCtx.createGain();
    this.ambientGain.gain.setValueAtTime(0.01, this.audioCtx.currentTime);
    this.ambientGain.gain.exponentialRampToValueAtTime(0.12, this.audioCtx.currentTime + 3);
    this.ambientGain.connect(this.audioCtx.destination);

    // Deep sub drone (55Hz - A1)
    const osc1 = this.audioCtx.createOscillator();
    osc1.type = 'sine';
    osc1.frequency.setValueAtTime(55, this.audioCtx.currentTime);

    // Low octave shimmer (110Hz - A2)
    const osc2 = this.audioCtx.createOscillator();
    osc2.type = 'triangle';
    osc2.frequency.setValueAtTime(110, this.audioCtx.currentTime);

    // Slow LFO for cosmic swell
    const lfo = this.audioCtx.createOscillator();
    lfo.type = 'sine';
    lfo.frequency.setValueAtTime(0.2, this.audioCtx.currentTime); // 0.2 Hz swell

    const lfoGain = this.audioCtx.createGain();
    lfoGain.gain.setValueAtTime(15, this.audioCtx.currentTime);

    lfo.connect(lfoGain);
    lfoGain.connect(osc2.frequency);

    osc1.connect(this.ambientGain);
    osc2.connect(this.ambientGain);

    osc1.start();
    osc2.start();
    lfo.start();

    this.oscillators = [osc1, osc2, lfo];
    this.isAmbientPlaying = true;
  }

  stopAmbientSound() {
    if (!this.isAmbientPlaying || !this.ambientGain) return;

    if (this.ambientGain && this.audioCtx) {
      this.ambientGain.gain.exponentialRampToValueAtTime(0.0001, this.audioCtx.currentTime + 1.5);
      setTimeout(() => {
        this.oscillators.forEach(osc => {
          try { osc.stop(); } catch (e) {}
        });
        this.oscillators = [];
        this.isAmbientPlaying = false;
      }, 1500);
    }
  }

  playClickSound() {
    this.initContext();
    if (!this.audioCtx) return;

    const osc = this.audioCtx.createOscillator();
    const gain = this.audioCtx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(800, this.audioCtx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(400, this.audioCtx.currentTime + 0.08);

    gain.gain.setValueAtTime(0.08, this.audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.audioCtx.currentTime + 0.08);

    osc.connect(gain);
    gain.connect(this.audioCtx.destination);

    osc.start();
    osc.stop(this.audioCtx.currentTime + 0.08);
  }

  playSuccessChime() {
    this.initContext();
    if (!this.audioCtx) return;

    const notes = [523.25, 659.25, 783.99, 1046.50]; // C5, E5, G5, C6
    notes.forEach((freq, idx) => {
      const osc = this.audioCtx.createOscillator();
      const gain = this.audioCtx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, this.audioCtx.currentTime + idx * 0.1);

      gain.gain.setValueAtTime(0.1, this.audioCtx.currentTime + idx * 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, this.audioCtx.currentTime + idx * 0.1 + 0.6);

      osc.connect(gain);
      gain.connect(this.audioCtx.destination);

      osc.start(this.audioCtx.currentTime + idx * 0.1);
      osc.stop(this.audioCtx.currentTime + idx * 0.1 + 0.6);
    });
  }
}

export const spaceAudio = new SpaceAudioSynthesizer();
